import{_ as e,o as a,c as s,ai as i}from"./chunks/framework.DQi1ytmF.js";const g=JSON.parse('{"title":"Coding agents","description":"Point Cursor, Claude, Copilot, and other coding agents at Craft NG docs, MCP tools, and Agent Skills after you import @craft-ng/core.","frontmatter":{"description":"Point Cursor, Claude, Copilot, and other coding agents at Craft NG docs, MCP tools, and Agent Skills after you import @craft-ng/core."},"headers":[],"relativePath":"resources/ai-agents.md","filePath":"resources/ai-agents.md"}'),n={name:"resources/ai-agents.md"};function l(o,t,d,r,c,h){return a(),s("div",null,[...t[0]||(t[0]=[i(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/resources/ai-agents.md for this page in Markdown format</div><h1 id="coding-agents" tabindex="-1">Coding agents <a class="header-anchor" href="#coding-agents" aria-label="Permalink to &quot;Coding agents&quot;">​</a></h1><p>Craft NG is unusual enough that a model trained on Angular classes will invent the wrong API. After you import <code>@craft-ng/core</code>, give the agent three layered entry points — the same split Angular uses with <code>llms.txt</code>, the CLI MCP server, and Agent Skills.</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it is</th><th>When the agent uses it</th></tr></thead><tbody><tr><td><strong>LLM files</strong></td><td><a href="https://ng-angular-stack.github.io/craft/llms.txt" target="_blank" rel="noreferrer"><code>/llms.txt</code></a>, <a href="https://ng-angular-stack.github.io/craft/llms-full.txt" target="_blank" rel="noreferrer"><code>/llms-full.txt</code></a>, and a <code>.md</code> sibling for every docs page</td><td>Discovery on the internet, no install</td></tr><tr><td><strong>MCP server</strong></td><td><a href="https://www.npmjs.com/package/@craft-ng/mcp" target="_blank" rel="noreferrer"><code>@craft-ng/mcp</code></a> — <code>get_best_practices</code>, <code>search_documentation</code>, <code>find_examples</code>, skills</td><td>Live lookup in Cursor, Claude Code, VS Code, Copilot</td></tr><tr><td><strong>Agent Skills</strong></td><td><code>skills/</code> inside <code>@craft-ng/mcp</code>, plus an <a href="https://agent-plugins.org/" target="_blank" rel="noreferrer">Agent Plugin</a> manifest</td><td>Multi-step workflows (routes, spec → primitives, migration)</td></tr></tbody></table><p>Do not scrape the HTML docs. Start from <code>llms.txt</code> or the MCP tools.</p><h2 id="_1-llm-files" tabindex="-1">1. LLM files <a class="header-anchor" href="#_1-llm-files" aria-label="Permalink to &quot;1. LLM files&quot;">​</a></h2><p>These follow the <a href="https://llmstxt.org/" target="_blank" rel="noreferrer">llms.txt</a> spec and are generated from this VitePress site at build time.</p><ul><li>Index (curated links): <a href="https://ng-angular-stack.github.io/craft/llms.txt" target="_blank" rel="noreferrer">https://ng-angular-stack.github.io/craft/llms.txt</a></li><li>Concatenated docs: <a href="https://ng-angular-stack.github.io/craft/llms-full.txt" target="_blank" rel="noreferrer">https://ng-angular-stack.github.io/craft/llms-full.txt</a></li><li>One page, as markdown: append <code>.md</code> to any docs URL, for example <a href="https://ng-angular-stack.github.io/craft/guide/state/local-state.md" target="_blank" rel="noreferrer">local state</a></li></ul><p>Paste this into an <code>AGENTS.md</code> (or <code>CLAUDE.md</code>) at the root of the app that imports Craft:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Craft NG</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">This application uses </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`@craft-ng/core\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Docs index: https://ng-angular-stack.github.io/craft/llms.txt</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MCP: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`npx -y @craft-ng/mcp@beta\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`get_best_practices\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`search_documentation\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Skills: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`node_modules/@craft-ng/mcp/skills\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">yield* every Craft reader. Do not generate Angular signal(), inject(), or</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@Injectable in authored Craft code. craftRoutes files need componentDeps and</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a per-file DI check.</span></span></code></pre></div><p>The same snippet is returned by the MCP tool <code>get_best_practices</code> (field <code>agentsMd</code>) and lives in the package as <code>content/agents.md</code>.</p><h2 id="_2-mcp-server" tabindex="-1">2. MCP server <a class="header-anchor" href="#_2-mcp-server" aria-label="Permalink to &quot;2. MCP server&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @craft-ng/mcp@beta</span></span></code></pre></div><p>Add a project <code>.mcp.json</code> (Cursor, Claude Code, and VS Code all understand it):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;craft-ng&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@craft-ng/mcp@beta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Claude Code, from the app directory:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft-ng</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @craft-ng/mcp@beta</span></span></code></pre></div><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Use it to</th></tr></thead><tbody><tr><td><code>get_best_practices</code></td><td>Load the coding-agent guide and the <code>AGENTS.md</code> snippet</td></tr><tr><td><code>search_documentation</code></td><td>Find a Guide / Learn / Reference page by API or task</td></tr><tr><td><code>get_documentation_page</code></td><td>Read one page as markdown (<code>/guide/state/local-state</code>)</td></tr><tr><td><code>find_examples</code></td><td>Find Learn + demo examples</td></tr><tr><td><code>list_skills</code> / <code>get_skill</code></td><td>Load a workflow skill and its <code>references/*.md</code></td></tr><tr><td><code>get_llms_txt</code></td><td>Get the public <code>llms.txt</code> URLs and the bundled path index</td></tr></tbody></table><p>The server is <strong>read-only</strong>. It searches documentation bundled at publish time, so it works offline. It is not the runtime registry MCP used to mutate a live demo tab.</p><h2 id="_3-agent-skills" tabindex="-1">3. Agent Skills <a class="header-anchor" href="#_3-agent-skills" aria-label="Permalink to &quot;3. Agent Skills&quot;">​</a></h2><p>Skills follow the <a href="https://agentskills.io/specification" target="_blank" rel="noreferrer">Agent Skills</a> layout (<code>SKILL.md</code> + optional <code>references/</code>). The package is also an Agent Plugin (<code>plugin.json</code> + <code>mcp.json</code> + <code>skills/</code>).</p><table tabindex="0"><thead><tr><th>Skill</th><th>Trigger</th></tr></thead><tbody><tr><td><code>craft-ng</code></td><td>Any authored Craft code</td></tr><tr><td><code>translate-spec-to-ng-craft</code></td><td>Spec / CRUD / filters / forms → primitives</td></tr><tr><td><code>ng-craft-routes</code></td><td><code>craftRoutes</code>, <code>componentDeps</code>, <code>TS2589</code></td></tr><tr><td><code>ng-craft-service-migration</code></td><td><code>@Injectable</code> / <code>inject()</code> → <code>craftService</code></td></tr><tr><td><code>migrate-to-ng-craft</code></td><td><code>craft-migrate</code> then manual diagnostics</td></tr></tbody></table><p>Point the agent at <code>node_modules/@craft-ng/mcp/skills</code>, or let it call <code>get_skill</code>. Cursor can also install a skill from that folder.</p><h2 id="verify-the-agent-can-see-craft" tabindex="-1">Verify the agent can see Craft <a class="header-anchor" href="#verify-the-agent-can-see-craft" aria-label="Permalink to &quot;Verify the agent can see Craft&quot;">​</a></h2><p>Ask it to add a <code>state</code> counter, a paged <code>query</code>, or a <code>craftRoutes</code> file. It should <code>yield*</code> readers, compose insertions with <code>craftPipe</code>, and put a DI check in the routes file. If it emits <code>signal()</code>, <code>inject()</code>, or a plain Angular <code>Routes</code> array, the MCP server or <code>AGENTS.md</code> snippet is not in context.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/craft/guide/concepts/choose-primitive.html">Which primitive should I use?</a></li><li><a href="/craft/guide/concepts/mental-model.html">The mental model</a></li><li><a href="/craft/guide/routing/automation.html">CLI automation</a></li><li><a href="/craft/resources/migration.html">Migration</a></li></ul>`,28)])])}const k=e(n,[["render",l]]);export{g as __pageData,k as default};
